WITH lines AS (SELECT id, host, log_ts, level, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, value), cleaned AS (SELECT id, host, status_code, key, value, CONCAT_WS('/', key, host) AS key_host_key, COALESCE(key, 'NONE') AS key_filled FROM lines WHERE log_ts > DATE '2025-06-01' AND status_code > 273), metrics AS (SELECT host, status_code, value, key_host_key, PERCENT_RANK() OVER (ORDER BY status_code DESC) AS status_code_percent_rank, ROUND(status_code / SUM(status_code) OVER (PARTITION BY host), 4) AS status_code_share, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) AS status_code_share_2, PERCENT_RANK() OVER (PARTITION BY host ORDER BY status_code DESC) AS status_code_percent_rank_2, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) AS status_code_share_3 FROM cleaned), cleaned_app_logs AS (SELECT host, status_code, value, status_code_percent_rank, status_code_share, status_code_share_2, status_code_percent_rank_2, ROUND(status_code_percent_rank_2, 2) AS status_code_percent_rank_2_rounded, ROUND(status_code_share_2, 2) AS status_code_share_2_rounded FROM metrics WHERE status_code > 371), report AS (SELECT host, status_code, value, status_code_percent_rank, status_code_share_2, status_code_percent_rank_2_rounded FROM cleaned_app_logs) SELECT host, status_code, value, status_code_percent_rank, status_code_share_2, status_code_percent_rank_2_rounded, CASE WHEN host RLIKE '^(h1|h4)$' THEN 'OTHER_ZONE' WHEN host RLIKE '^(h2|h3)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS host_zone FROM report ORDER BY status_code_percent_rank_2_rounded DESC
